    practiseFun(val1, val2) {
        console.log("practiseFun", val1, val2);
        let sum = "";
        if (val1 == "0" || val2 == "0") {
            sum = val1 + val2;
        }
        else {
            sum = (val1 + val2) / 2;
        }
        return Math.round(sum) + "%";

    }
    examFun(val1, val2) {
        let sum = "";
        if (val1 == "0" || val2 == "0") {
            sum = val1 + val2;
        }
        else {
            sum = (val1 + val2) / 2;
        }
        return Math.round(sum) + "%";
    }
    strengthCuttOff = (e, subject) => {
        console.log("strengthCuttOff", subject);
        this.setState({
            strengthCuttOffVal: e.target.value,
            subject: subject
        });

    }
    tabledata(data) {
        let returnArr = [];
        data.map((item) => {
            const newObj = {
                questions: item.complexity,
                accuracy: parseInt(item.accuracy),
                correct: parseInt(item.correct),
                skipped: parseInt(item.skipped),
                error: parseInt(item.wrong),
            }
            returnArr.push(newObj);
        });
        return returnArr;
    }
